def max_subarray(a)
  best=a[0];cur=a[0]
  a[1..].each{|x| cur=[x,cur+x].max; best=[best,cur].max}
  best
end

def max_profit(prices)
  return 0 if prices.empty?
  minp=prices[0];best=0
  prices.each{|p| minp=[minp,p].min; best=[best,p-minp].max}
  best
end

def unique_paths(m,n)
  dp=Array.new(n,1)
  (1...m).each{ (1...n).each{|j| dp[j]+=dp[j-1]} }
  dp[n-1]
end

def product_except_self(a)
  n=a.length;res=Array.new(n,1)
  pre=1;(0...n).each{|i| res[i]=pre;pre*=a[i]}
  post=1;(n-1).downto(0){|i| res[i]*=post;post*=a[i]}
  res
end

def count_bits(n)
  (0..n).map{|i| i.to_s(2).count("1")}
end

def group_by_length(words)
  words.each_with_object(Hash.new{|h,k| h[k]=[]}){|w,h| h[w.length]<<w}
end

def factorial_reduce(n)
  (1..n).reduce(1,:*)
end

def pipe(x)
  x.then{|v| v+1}.then{|v| v*2}
end

