class LRUCache
  def initialize(cap); @cap=cap; @h={}; end
  def get(k)
    return nil unless @h.key?(k)
    v=@h.delete(k); @h[k]=v; v
  end
  def put(k,v)
    @h.delete(k); @h[k]=v
    @h.delete(@h.keys.first) if @h.size>@cap
  end
end
